window.HOEREN_TESTS[44] = {"id":"im-museum","name":"Im Museum","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Museums-Besucher: Das Naturkunde-Museum hat ab Montag neue Öffnungszeiten. Wir sind nicht mehr Montag bis Sonntag offen, sondern Dienstag bis Sonntag, jeweils 10 bis 18 Uhr. Nicht Sonntag und nicht Mittwoch, nur Montag ist Ruhetag. Eintritt 8 Euro für Erwachsene. Kinder unter 12 sind frei. Vielen Dank für Ihren Besuch!","gender":"m","q":"Wann ist Ruhetag?","opts":["Montag.","Sonntag.","Mittwoch."],"correct":0},{"transcript":"Hallo Lisa, hier ist Anna. Pass auf, das neue Kunst-Museum in der Stadt eröffnet am Samstag! Es schließt nicht und ist nicht umgezogen, es ist ganz neu! Eintritt ist die erste Woche frei. Lass uns hingehen, vielleicht Samstag oder Sonntag. Wir können auch ins Café danach. Ruf mich an, wir machen Termin. Bis bald!","gender":"f","q":"Was ist besonderes?","opts":["Es schließt.","Es eröffnet neu.","Es ist umgezogen."],"correct":1},{"transcript":"Achtung Besucher: Im Saal 7, der ägyptischen Sammlung, ist die Klimaanlage kaputt. Es ist sehr warm dort heute. Die Beleuchtung geht noch, und der Saal ist nicht gesperrt. Wir empfehlen einen kurzen Besuch oder zuerst andere Räume. Reparatur kommt morgen. Wir entschuldigen uns. Saal 7 bleibt geöffnet, aber Vorsicht.","gender":"f","q":"Was ist das Problem im Saal 7?","opts":["Klimaanlage kaputt.","Beleuchtung kaputt.","Saal gesperrt."],"correct":0},{"transcript":"Liebe Schulklasse 5A: Eure Führung im Museum startet pünktlich um 10 Uhr. Treffpunkt am Haupteingang. Eine Kamera braucht ihr nicht mitbringen, nur ein kleines Notebook für Notizen. Mittagessen gibt es um 12 Uhr im Café. Achtet bitte auf Ruhe — andere Besucher sind auch da. Bis morgen! Wir sehen uns morgen!","gender":"m","q":"Was sollen die Kinder mitbringen?","opts":["Eine Kamera.","Ein Notebook.","Mittagessen."],"correct":1},{"transcript":"Hi Markus, hier ist Tom. Ich habe meine Museumskarte verloren. Nicht vergessen, wirklich verloren. Und krank bin ich auch nicht. Habe schon angerufen, sie machen Ersatz. Aber dauert eine Woche. Heute kann ich nicht mit ins Museum, Eintritt zu teuer ohne Karte. Geh ohne mich, sorry. Nächste Woche dann zusammen.","gender":"m","q":"Was geht heute nicht?","opts":["Tom hat die Karte vergessen.","Tom ist krank.","Tom hat die Karte verloren."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer mag was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Am Samstag sind im Museum fünf Abteilungen auf."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Wir müssen uns trennen. Sonst schaffen wir nicht alles in Ruhe."},{"speaker":"Lukas","gender":"m","text":"Ich gehe in die Geschichte. Alte Karten interessieren mich sehr."},{"speaker":"Lisa","gender":"f","text":"Dort bleibst du sicher lange. Ich will Farbe und große Formen."},{"speaker":"Lukas","gender":"m","text":"Will noch jemand in die Abteilung für Sport?"},{"speaker":"Lisa","gender":"f","text":"Nein. Sport sehen wir uns nicht an."},{"speaker":"Lukas","gender":"m","text":"Dann suchst du die helle Halle mit den neuen Werken."},{"speaker":"Lisa","gender":"f","text":"Ich schaue mir Moderne Kunst an. Die Bilder hängen im Obergeschoss."},{"speaker":"Lukas","gender":"m","text":"Tom bleibt immer bei den Tieren und Steinen stehen."},{"speaker":"Lisa","gender":"f","text":"Tom geht in die Naturkunde. Das Skelett dort ist wirklich riesig."},{"speaker":"Lukas","gender":"m","text":"Sara redet seit Tagen nur über Pyramiden."},{"speaker":"Lisa","gender":"f","text":"Sara geht in den Saal für Ägypten. Die Maske liegt ganz hinten."},{"speaker":"Lukas","gender":"m","text":"Hat noch jemand Zeit für Mode?"},{"speaker":"Lisa","gender":"f","text":"Nein. Für Mode hat auch keiner Zeit."},{"speaker":"Lukas","gender":"m","text":"Tim will die großen Maschinen in Bewegung sehen."},{"speaker":"Lisa","gender":"f","text":"Tim schaut sich Technik an. Er bleibt dort den ganzen Nachmittag."},{"speaker":"Lukas","gender":"m","text":"Um vier treffen wir uns unten im Café."},{"speaker":"Lisa","gender":"f","text":"Ich warte dann an der Garderobe auf euch."}],"options":[{"letter":"a","text":"Sport"},{"letter":"b","text":"Klassische Kunst"},{"letter":"c","text":"Technik"},{"letter":"d","text":"Naturkunde"},{"letter":"e","text":"Moderne Kunst"},{"letter":"f","text":"Musik"},{"letter":"g","text":"Ägypten"},{"letter":"h","text":"Mode"},{"letter":"i","text":"Geschichte"}],"items":[{"person":"Lukas","correct":"i"},{"person":"Lisa","correct":"e"},{"person":"Tom","correct":"d"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Besucher","gender":"m","text":"Guten Tag! Was kostet der Eintritt für Erwachsene?"},{"speaker":"Kassiererin","gender":"f","text":"Erwachsene zahlen 10 Euro, ermäßigt 6 Euro. Kostenlos ist es leider nie, auch nicht am Sonntag."},{"speaker":"Besucher","gender":"m","text":"Ich bin Student. Zahle ich auch 6 Euro?"},{"speaker":"Kassiererin","gender":"f","text":"Ja, mit Studentenkarte zahlen Sie 6 Euro, bitte schön."},{"speaker":"Besucher","gender":"m","text":"Gut, hier ist meine Karte. Vielen Dank! Super!"}],"q":"Was zahlt der Student?","opts":["10 Euro.","6 Euro.","Kostenlos."],"correct":1},{"lines":[{"speaker":"Touristin","gender":"f","text":"Entschuldigung, wo finde ich die Picasso-Ausstellung?"},{"speaker":"Mitarbeiter","gender":"m","text":"Im ersten Stock, Saal 5. Nehmen Sie die Rolltreppe oder den Aufzug."},{"speaker":"Touristin","gender":"f","text":"Gut, dann nehme ich den Aufzug."},{"speaker":"Mitarbeiter","gender":"m","text":"Oh, der Aufzug ist heute kaputt. Bitte nehmen Sie die Treppe."},{"speaker":"Touristin","gender":"f","text":"Na gut, dann die Treppe. Vielen Dank! Sport ist gesund."}],"q":"Wie kommt die Touristin nach oben?","opts":["Treppe.","Aufzug.","Rolltreppe."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, kann ich hier ein Foto machen?"},{"speaker":"Vater","gender":"m","text":"Frag bitte die Mitarbeiterin, ich weiß es nicht."},{"speaker":"Mitarbeiterin","gender":"f","text":"Fotografieren ist erlaubt, aber bitte ohne Blitz. Und leise sprechen, ja?"},{"speaker":"Tochter","gender":"f","text":"Okay, ohne Blitz und ganz leise. Schau, so mache ich es."},{"speaker":"Mitarbeiterin","gender":"f","text":"Perfekt! Viel Spaß im Museum! Es gibt viel zu sehen!"}],"q":"Was ist nicht erlaubt?","opts":["Fotografieren.","Sprechen.","Blitz."],"correct":2},{"lines":[{"speaker":"Besucher1","gender":"m","text":"Wie lange dauert die Führung durch das Museum?"},{"speaker":"Führerin","gender":"f","text":"Normalerweise 60 Minuten, mit allen Sälen."},{"speaker":"Besucher1","gender":"m","text":"Das ist zu lang. Gibt es eine kurze Version?"},{"speaker":"Führerin","gender":"f","text":"Ja, 30 Minuten nur mit den Highlights. Oder gar keine Führung, nur Audio-Guide."},{"speaker":"Besucher1","gender":"m","text":"Dann nehmen wir die kurze Führung für 30 Minuten. Wo geht es los?"}],"q":"Welche Führung wählen sie?","opts":["60 Minuten.","30 Minuten.","Keine."],"correct":1},{"lines":[{"speaker":"Mutter","gender":"f","text":"Klein-Lukas, sei vorsichtig! Fass nichts an!"},{"speaker":"Mitarbeiter","gender":"m","text":"Bitte das Kunstwerk nicht berühren! Er hat es angefasst!"},{"speaker":"Mutter","gender":"f","text":"Oh nein, Entschuldigung! Er hat es nicht gewusst. Er hat nichts zerbrochen, oder?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nein, nichts zerbrochen, alles gut. Und geschrien hat er auch nicht, braver Junge."},{"speaker":"Mutter","gender":"f","text":"Komm, Lukas, wir schauen nur noch mit den Augen."}],"q":"Was ist passiert?","opts":["Kind hat etwas zerbrochen.","Kind hat geschrien.","Kind hat Kunst berührt."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Sommer, einem Museumsdirektor. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Sommer, Sie leiten das Kunst-Museum seit 10 Jahren. Wie war Ihr Werdegang?"},{"speaker":"Sommer","gender":"m","text":"Ich habe Kunstgeschichte studiert, dann am Museum als normaler Mitarbeiter angefangen. Schritt für Schritt nach oben — Sammlungsleiter, dann stellvertretender Direktor, jetzt Direktor. Brauchte 20 Jahre — Geduld ist wichtig im Kultur-Bereich."},{"speaker":"Reporterin","gender":"f","text":"Wie hat sich die Museumswelt verändert?"},{"speaker":"Sommer","gender":"m","text":"Sehr stark, früher waren Museen nur für Bildung — heute mehr Erlebnis. Interaktive Stationen, Apps, virtuelle Reality. Jüngere Besucher wollen das. Klassische ‚Schau-aber-fass-nicht-an‘ Museen verlieren Publikum."},{"speaker":"Reporterin","gender":"f","text":"Wie viele Besucher kommen jährlich?"},{"speaker":"Sommer","gender":"m","text":"Etwa 250.000 pro Jahr. Vor 10 Jahren waren es 180.000 — wir sind gewachsen. Sonderausstellungen ziehen besonders viele. Letzte Ausstellung Picasso — 80.000 in drei Monaten allein!"},{"speaker":"Reporterin","gender":"f","text":"Was ist die größte Herausforderung?"},{"speaker":"Sommer","gender":"m","text":"Geld. Museen werden weniger gefördert vom Staat. Wir brauchen Sponsoren, private Spenden, Eintrittsgelder. Balance zwischen Kommerz und Kunst ist schwer. Aber wir kämpfen weiter."},{"speaker":"Reporterin","gender":"f","text":"Wie sehen Sie die Zukunft?"},{"speaker":"Sommer","gender":"m","text":"Schwierig, aber spannend. Digitale Museen kommen — Online-Touren, virtuelle Ausstellungen. Echte Museen werden bleiben — Originale sehen ist unschlagbar. Aber wir müssen uns verändern, modernisieren. Wer das nicht tut, schließt."}],"items":[{"q":"Herr Sommer wurde sofort Direktor nach dem Studium.","correct":"nein"},{"q":"Heute sind interaktive Stationen wichtig in Museen.","correct":"ja"},{"q":"Das Museum hat heute weniger Besucher als vor 10 Jahren.","correct":"nein"},{"q":"Die größte Herausforderung ist finanzieller Natur.","correct":"ja"},{"q":"Er glaubt, echte Museen werden bald geschlossen.","correct":"nein"}]}]};
